OJA_ROME.add("K2138",{"code":"K2138","t":"Animateur / Animatrice de stages permis à points","dom":"Formation initiale et continue","a":[],"d":"L' Animateur de stages permis à points sensibilise à la sécurité routière. Coanime les sessions avec un animateur psychologue Coanime des sessions de sensibilisation à la sécurité routière pour les conducteurs ayant perdu des points sur leur permis Utilise des supports pédagogiques pour faciliter la compréhension et l'apprentissage des participants Évalue les connaissances des participants en début et fin de session pour mesurer l'impact de la formation Encourage les échanges et discussions entre les participants pour partager les expériences et renforcer les messages clés Met à jour régulièrement ses connaissances sur les réglementations routières pour fournir des informations précises Assure le suivi administratif des stages et la délivrance des attestations de participation","acc":"L'animateur expert en sécurité routière doit obligatoirement être titulaire de l'autorisation d'enseigner la conduite et la sécurité routière et, soit du brevet d'aptitude à la formation des moniteurs (BAFM), soit du brevet d'animateur pour la formation des conducteurs responsables d'infractions (BAFCRI) . La possession d'un permis de conduire catégorie B est également utile mais non obligatoire. Chacun des animateurs doit être titulaire d'une autorisation d'animer, valable sur tout le territoire national, délivrée par la préfecture de son lieu de résidence, ou s'il réside à l'étranger, du département dans lequel il envisage d'exercer. Cette autorisation d'animer, soumise à renouvellement tous les cinq ans, est délivrée aux personnes remplissant les conditions suivantes : avoir 25 ans minimum ; ne pas avoir fait l'objet d'une condamnation à une peine criminelle, ou à une peine correctionnelle pour l'une des infractions mentionnées à l'article R. 212-4 du code de la route ; avoir suivi la formation initiale à l'animation des stages de sensibilisation à la sécurité routière, d'une durée de cinq semaines, dispensée par l'Institut national de sécurité routière et de recherches (Inserr)","sf":[["Conseil, Transmission","Dispenser un programme de formation visant à impulser un processus de changement d'attitudes et de comportements chez le conducteur infractionniste",511459,1],["Conseil, Transmission","Déterminer les capacités des candidats à la conduite de véhicules",300510,0],["Conseil, Transmission","Encourager l'interaction lors des sessions de formation",507700,0],["Conseil, Transmission","Evaluer des acquis d'apprentissage, de formation ou d'expérience",300018,1],["Conseil, Transmission","Informer les stagiaires sur les règles de sécurité routière, les effets de l'alcool et des drogues sur la conduite, la fatigue au volant, etc",511463,1],["Conseil, Transmission","Organiser des sessions de formation continue",482189,0],["Conseil, Transmission","Sensibiliser aux causes et conséquences des accidents de la route pour éviter la réitération des infractions",511460,1],["Conseil, Transmission","Stimuler les échanges et les discussions entre les participants pour favoriser l'engagement et la prise de conscience individuelle",511462,1],["Conseil, Transmission","Utiliser des méthodes pédagogiques variées pour favoriser l'apprentissage (cas pratiques, ateliers, simulations)",511612,0],["Qualité","Evaluer l'efficacité des stages sur les comportements des conducteurs",505701,1],["Gestion administrative et comptable","Assurer le suivi administratif des stagiaires (attestations de participation, transmission des informations aux préfectures, etc)",511464,1],["Pilotage et maîtrise des coûts","Assurer la gestion administrative d'une activité",124377,1],["Relation client","Accueillir, orienter, renseigner un public",300361,1],["Communication","Animer des sessions de formation",482619,0],["Organisation","Gérer les conflits lors de sessions de formation",499728,1],["Organisation","Surveiller le respect des règles durant les stages",505699,0],["Organisation","Utiliser les outils numériques",300426,0]],"se":[["Avoir le sens du service",399999],["Faire preuve de rigueur et de précision",300490],["Inspirer, donner du sens",300416]],"sv":[["Produits, outils et matières","Utilisation de matériel audiovisuel",481546,0],["Domaines d'expertise","Utilisation de logiciels de présentation",499165,0],["Normes et procédés","Règles de conduite et de sécurité routière",108568,1],["Techniques professionnelles","Techniques de gestion administrative",498131,0],["Techniques professionnelles","Techniques d'animation de groupes",102344,0],["Techniques professionnelles","Techniques de feedback constructif",476865,1],["Techniques professionnelles","Dynamique de groupe",494083,0],["Techniques professionnelles","Techniques d'évaluation",493646,0],["Techniques professionnelles","Techniques de présentation orale",477795,0],["Techniques professionnelles","Techniques de motivation",477209,0],["Techniques professionnelles","Techniques de questionnement",498564,1]],"cert":[["Permis de conduire catégorie B",123456],["Formateur aux métiers de l'éducation et de la sécurité routières",512444]],"ctx":[["Statut d'emploi","Salarié secteur privé (CDI, CDD)",403103],["Conditions de travail et risques professionnels","Déplacements professionnels",300779],["Conditions de travail et risques professionnels","En contact avec du public",403020],["Conditions de travail et risques professionnels","En extérieur",300783],["Conditions de travail et risques professionnels","Station debout prolongée",300800],["Horaires et durée du travail","Travail en journée",300806],["Horaires et durée du travail","Travail selon un rythme irrégulier et des pics d'activité",403095],["Types de structures","Organisme de formation",405286]]});
